export function Component({
  variant = "{{variant}}",
  size = {{size}},
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  const styles = {
    primary: { background: accent, color: "#FAF7F2", borderStyle: "solid" },
    secondary: { background: "transparent", color: accent, borderStyle: "solid" },
    danger: { background: "#fff", color: accent, borderStyle: "dashed" },
  }[variant];
  const Instance = ({ suffix }) => (
    <button type="button" style={{ fontWeight: 600, padding: "8px 12px", borderRadius: 8, cursor: "pointer", border: `1.5px ${styles.borderStyle} ${accent}`, fontSize: size, background: styles.background, color: styles.color }}>
      {label} {suffix}
    </button>
  );
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      <p style={{ margin: "0 0 12px" }}>One component definition, three independent instances:</p>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
        <Instance suffix="A" />
        <Instance suffix="B" />
        <Instance suffix="C" />
      </div>
    </div>
  );
}
